result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/life.test.ts", "content": "import { describe, expect, it } from "vitest";
import { run, step, toSet, translate, type Cell } from "../src/life.js";

// Blinker: vertical bar of 3 cells.
const blinker: Cell[] = [
  [1, 0],
  [1, 1],
  [1, 2],
];

// Glider pointing down-right.
const glider: Cell[] = [
  [0, 1],
  [1, 2],
  [2, 0],
  [2, 1],
  [2, 2],
];

// Block: 2x2 square.
const block: Cell[] = [
  [0, 0],
  [0, 1],
  [1, 0],
  [1, 1],
];

describe("Game of Life", () => {
  it("blinker has period 2", () => {
    const gen1 = step(blinker, 10, 10);
    const gen2 = step(gen1, 10, 10);
    expect(toSet(gen2)).toEqual(toSet(blinker));
    expect(toSet(gen1)).not.toEqual(toSet(blinker));
  });

  it("glider returns translated by (1,1) after 4 gens on a 20x20 torus", () => {
    const after4 = run(glider, 4, 20, 20);
    expect(toSet(after4)).toEqual(toSet(translate(glider, 1, 1, 20, 20)));
  });

  it("block is a still life over 10 generations", () => {
    expect(toSet(run(block, 10, 10, 10))).toEqual(toSet(block));
  });

  it("glider population stays 5 throughout", () => {
    let state = glider;
    for (let g = 0; g < 4; g++) {
      expect(state).toHaveLength(5);
      state = step(state, 20, 20);
    }
  });
});
"})
