result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/life.ts", "content": "export type Cell = readonly [x: number, y: number];

/** Conway's Life step on a toroidal (wrap-around) grid of size w x h. */
export function step(cells: Cell[], w: number, h: number): Cell[] {
  const counts = new Map<number, number>();
  const key = (x: number, y: number) => ((y % h) + h) * w + (((x % w) + w) % w);
  const live = new Set<number>();
  for (const [x, y] of cells) {
    const k = key(x, y);
    if (!live.has(k)) {
      live.add(k);
      counts.set(k, counts.get(k) ?? 0);
    }
    for (let dy = -1; dy <= 1; dy++)
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nk = key(x + dx, y + dy);
        counts.set(nk, (counts.get(nk) ?? 0) + 1);
      }
  }
  const out: Cell[] = [];
  for (const [k, n] of counts) {
    const isLive = live.has(k);
    if (n === 3 || (isLive && n === 2)) out.push([k % w, Math.floor(k / w)]);
  }
  return out;
}

/** Run `gens` steps of the simulation. */
export function run(cells: Cell[], gens: number, w: number, h: number): Cell[] {
  let state = cells;
  for (let i = 0; i < gens; i++) state = step(state, w, h);
  return state;
}

/** Translate cells by (dx, dy), wrapping on a w x h torus. */
export function translate(
  cells: Cell[],
  dx: number,
  dy: number,
  w: number,
  h: number,
): Cell[] {
  return cells.map(([x, y]) => [(((x + dx) % w) + w) % w, (((y + dy) % h) + h) % h]);
}

/** Normalize to a comparable set of coordinate pairs. */
export function toSet(cells: Cell[]): Set<string> {
  return new Set(cells.map(([x, y]) => `${x},${y}`).sort());
}
"})
